package com.hfr.inventory.gui;
import java.io.*; import java.util.*; import com.hfr.main.MainRegistry; import net.minecraft.client.Minecraft; import net.minecraft.client.gui.*; import net.minecraft.util.StatCollector; import org.lwjgl.input.Keyboard; import cpw.mods.fml.relauncher.*;
@SideOnly(Side.CLIENT) public class GUIXenofactionsTutorial extends GuiScreen { private int page; private static final int PAGES=5; public boolean doesGuiPauseGame(){return false;} public void initGui(){buttonList.clear(); int y=height-28; buttonList.add(new GuiButton(1,width/2-154,y,70,20,StatCollector.translateToLocal("xf.tutorial.back"))); buttonList.add(new GuiButton(2,width/2-78,y,70,20,StatCollector.translateToLocal(page==PAGES-1?"xf.tutorial.finish":"xf.tutorial.next"))); buttonList.add(new GuiButton(3,width/2,y,96,20,StatCollector.translateToLocal("xf.tutorial.never"))); if(page==PAGES-1)buttonList.add(new GuiButton(4,width/2+102,y,120,20,StatCollector.translateToLocal("xf.tutorial.open_menu"))); ((GuiButton)buttonList.get(0)).enabled=page>0; }
 protected void actionPerformed(GuiButton b){ if(b.id==1){page--;initGui();} if(b.id==2){ if(page<PAGES-1){page++;initGui();} else {createFlag(); mc.displayGuiScreen(null);} } if(b.id==3){createFlag(); mc.displayGuiScreen(null);} if(b.id==4){createFlag(); GUIXenofactionsMenu.requestAndOpen();} }
 public void drawScreen(int mx,int my,float f){drawDefaultBackground(); drawCenteredString(fontRendererObj,StatCollector.translateToLocal("xf.tutorial.title"),width/2,16,0xffffff); List<String> lines=fontRendererObj.listFormattedStringToWidth(StatCollector.translateToLocal("xf.tutorial.page"+page),Math.max(220,width-80)); int y=44; for(String s:lines){drawString(fontRendererObj,s,40,y,0xe0e0e0); y+=12;} drawCenteredString(fontRendererObj,(page+1)+"/"+PAGES,width/2,height-43,0xa0a0a0); super.drawScreen(mx,my,f);} protected void keyTyped(char c,int k){ if(k==Keyboard.KEY_ESCAPE) mc.displayGuiScreen(null); }
 public static File getFlagFile(){return new File(Minecraft.getMinecraft().mcDataDir,"tutorialflag");} public static void createFlag(){File f=getFlagFile(); try{ if(!f.exists()) f.createNewFile(); }catch(IOException e){MainRegistry.logger.error("Could not create Xenofactions tutorial flag at "+f.getAbsolutePath(),e);} } public static void deleteFlag(){File f=getFlagFile(); if(f.exists()&&!f.delete()) MainRegistry.logger.error("Could not delete Xenofactions tutorial flag at "+f.getAbsolutePath());}}
